import {escapeHtml as esc} from './components.js';
import {rulesForUi} from './us-kr-view-model.js';
const pct=n=>Number.isFinite(n)?(n>0?'+':'')+n.toFixed(2)+'%':'—';
const num=n=>Number.isFinite(n)?n.toLocaleString('ko-KR',{maximumFractionDigits:2}):'—';
const stamp=(s,zone)=>s?new Intl.DateTimeFormat('ko-KR',{timeZone:zone,month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(s)):'미제공';
export function mountUsKr(root,{navigate}){
 let data=null,selected='all',sort='business',busy=false;
 function render(){
  const s=data?.snapshot,industries=(s?.industries||[]).filter(i=>i.eligible),industry=industries.find(i=>i.name===selected);if(selected!=='all'&&!industry)selected='all';
  const eligible=(data?.candidates||[]).filter(c=>c.status==='verified'&&industries.some(i=>c.industries.some(r=>r.name===i.name))),candidates=rulesForUi(eligible,selected==='all'?null:selected,sort,industries);
  root.innerHTML=`<div class="panel-heading"><div><div class="eyebrow">US → KOREA</div><h2>전날 미국장 → 오늘의 국내 연관 종목</h2></div><button class="button" data-related-refresh ${busy?'disabled':''}>${busy?'확인 중':'새로고침'}</button></div><div class="us-kr-body">${!s?`<p role="status">${esc(data?.message||'미국 산업과 국내 공시 근거를 확인하고 있어요.')}</p>`:`<p class="us-kr-dates">미국장 <strong>${esc(s.sessionDate)}</strong> → 다음 국내 거래일 <strong>${esc(s.targetDate)}</strong>${data.stale?' · <b>갱신 지연 · 저장 결과</b>':''}</p><p class="us-kr-note">정규장 마감 ${esc(stamp(s.closeAt,'America/New_York'))} ET / ${esc(stamp(s.closeAt,'Asia/Seoul'))} KST · 수집 ${esc(stamp(s.observedAt,'Asia/Seoul'))} KST</p>${data.message?`<p role="status">${esc(data.message)}</p>`:''}<div class="us-kr-industries" aria-label="강했던 미국 산업"><button data-related-industry="all" aria-pressed="${selected==='all'}"><strong>상승 산업 전체</strong><b>${industries.length}개</b><small>사업 근거 확인 후보 함께 보기</small></button>${industries.map(i=>`<button data-related-industry="${esc(i.name)}" aria-pressed="${selected===i.name}"><strong>${esc(i.name)}</strong><b>${pct(i.returnPct)}</b><small>상승 ${i.up}/${i.count}개 · ${(i.upRatio*100).toFixed(0)}%</small><small>${esc(i.pattern)}</small></button>`).join('')||'<p>집계 조건을 충족한 상승 산업이 없습니다.</p>'}</div>${industry?`<div class="us-kr-industry-summary"><strong>${esc(industry.name)}</strong><span>종목 중간값 ${pct(industry.returnPct)}</span><span>분석 시장 대비 ${num(industry.excess)}%p</span><span>거래량 ${num(industry.relativeVolume)}배 · ${industry.volumeCount}/${industry.count}개</span><details><summary>미국 구성종목·계산 기준</summary><p>수익률 대표값은 중간값입니다. 거래량은 Finviz의 최근 3개월 평균 대비 상대 거래량 중간값이며 전일 대비가 아닙니다. 분석 시장 중간값 ${pct(s.benchmark)} · ${s.count}/${s.targetCount}개 · ${esc(s.universe)}</p><p>시가총액 가중 평균 ${pct(industry.weightedReturn)} · 상승 기여 상위 2개 비중 ${Number.isFinite(industry.topTwoShare)?num(industry.topTwoShare*100)+'%':'—'}</p><div class="us-kr-us-stocks">${industry.stocks.map(x=>`<a href="/stock/US/${encodeURIComponent(x.ticker)}">${esc(x.name)} · ${pct(x.changePct)}</a>`).join('')}</div><a href="/?market=US&sector=${encodeURIComponent(industry.stocks.length?industry.sector||'':'')}">기존 미국 섹터맵 보기</a></details></div>`:''}<div class="us-kr-list-heading"><h3>사업 근거가 확인된 관찰 후보 <small>${candidates.length}개</small></h3><label>정렬 <select aria-label="국내 연관 종목 정렬"><option value="business">사업 연관도순</option><option value="reaction">과거 반응순</option><option value="strength">미국 산업 강도순</option></select></label></div><p class="us-kr-note">사업 연관도순은 확인된 관련 매출 비중순 · 과거 반응순은 20개 이상 표본의 지수 대비 중간값순입니다. 복수 사업이 확인된 기업은 사업별로 표시합니다.</p><div class="us-kr-candidates">${candidates.map(c=>card(c)).join('')||'<p class="us-kr-empty">이 산업과 사업 근거·매출 비중이 함께 확인된 국내 종목이 없습니다. 연관성 확인 중인 종목을 임의로 후보에 넣지 않습니다.</p>'}</div><details class="us-kr-pending"><summary>연관성 확인 중 · 수집 범위 ${data.checkedCount}/${data.targetCount}개 기업</summary>${(data.candidates||[]).filter(c=>c.status!=='verified'&&(selected==='all'||c.industries.some(r=>r.name===selected)||!c.industries.length)).map(c=>`<p><a href="${esc(c.stockUrl)}">${esc(c.name)}</a> · ${esc(c.topicName)} · ${esc(c.reason)}</p>`).join('')||'<p>선택한 산업의 미확인 연결이 없습니다.</p>'}<p>기업을 소량씩 순차 확인합니다. ETF·ETN·우선주는 후보에 포함하지 않습니다.</p></details><footer class="us-kr-note">${esc(s.source)} · ${esc(s.basis)}<br>국내 시세는 전일 기준 · 사업 연관성이 같은 방향의 주가 반응을 뜻하지 않습니다.<details><summary>데이터 범위·검증 한계</summary>${data.limitations.map(l=>`<p>${esc(l)}</p>`).join('')}<p>분류 ${esc(s.version)} · 달력 ${esc(data.calendarThrough)}까지 · 결과 갱신 ${esc(stamp(data.updatedAt,'Asia/Seoul'))} KST</p></details></footer>`}</div>`;
  const select=root.querySelector('select');if(select)select.value=sort;
 }
 function card(c){const r=c.reactions,q=c.quote,relations=c.industries.filter(i=>selected==='all'||i.name===selected).map(i=>({same_product:'동일 제품·사업',component_equipment:'부품·장비 공급 영역',raw_material:'원재료 공급 영역',customer:'공시 확인 고객사',competitor:'공시 확인 경쟁사'}[i.relation]||i.relation));return `<article class="us-kr-card"><div class="us-kr-card-heading"><a href="${esc(c.stockUrl)}"><h4>${esc(c.marketName||c.name)}</h4><small>${esc(c.ticker)} · ${esc(c.sector||'')}</small></a><strong>${num(q.price)}원<small>${pct(q.changePct)}</small></strong></div><p><b>${esc(c.topicName)}</b> · ${esc(relations.join(' / '))}</p><p class="us-kr-evidence">${esc(c.products)} · 관련 매출 비중 ${num(c.revenueShare)}%</p><details><summary>사업 근거 공시 확인</summary><p>${esc(c.reportName)} · 발표일 ${esc(c.publishedDate)}</p><blockquote>${esc(c.evidence)}</blockquote><p>${esc(c.locator)} · 확인 ${esc(stamp(c.checkedAt,'Asia/Seoul'))} KST · ${esc(c.version)}</p><a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">DART 원문 ↗</a></details><div class="us-kr-reaction"><strong>과거 다음 거래일 반응</strong><p>${r.status==='ready'?`수익률 중간값 ${pct(r.median)} · 지수 대비 ${num(r.excessMedian)}%p`:'판단 자료 부족'}</p><small>표본 ${r.count}개 · 상승 ${r.up||0}회${r.from?' · '+esc(r.from)+' ~ '+esc(r.to):' · 검증 이력 축적 전'}</small><details><summary>과거 비교 내역</summary><p>${esc(r.reason)} · 기준 지수 ${esc(r.benchmark||'미확인')}</p>${r.samples.length?`<table><thead><tr><th>미국장 / 국내 거래일</th><th>수익률</th><th>지수 대비</th></tr></thead><tbody>${r.samples.map(p=>`<tr><td>${esc(p.usDate)} / ${esc(p.date)}</td><td>${pct(p.returnPct)}</td><td>${num(p.excess)}%p</td></tr>`).join('')}</tbody></table>`:'<p>현재 분류와 새 공시를 과거에 소급해 표본을 만들지 않습니다.</p>'}</details></div><small class="us-kr-note">전일 기준 ${esc(q.baseDate||'미확인')} · ${esc(q.source)}${q.stale?' · 갱신 지연':''}<br>시세 수집 ${esc(stamp(q.syncedAt,'Asia/Seoul'))} KST</small></article>`;}
 async function refresh(){if(busy)return;busy=true;render();try{const response=await fetch('/api/us-kr-links');if(!response.ok)throw Error();data=await response.json();}catch{data=data?{...data,stale:true,message:'연결 실패 · 마지막 화면 유지'}:{status:'error',message:'연관 종목 데이터를 불러오지 못했습니다.'};}finally{busy=false;render();}}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-related-industry]');if(b){selected=b.dataset.relatedIndustry;render();}if(e.target.closest('[data-related-refresh]'))refresh();const a=e.target.closest('a[href^="/"]');if(a&&!e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.getAttribute('href'));}});
 root.addEventListener('change',e=>{if(e.target.matches('select')){sort=e.target.value;render();}});
 refresh();return {refresh};
}
